                animate={{ scale: 1 }}
                exit={{ scale: 0 }}
                className="absolute -top-1.5 -right-1.5 bg-primary text-white text-[9px] font-black w-5 h-5 rounded-lg flex items-center justify-center shadow-md shadow-primary/20 border border-white"
              >
                {orderBookCount}
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>

        {/* Action 2: Interactive Menu Booklet Trigger Widget */}
        <motion.button
          whileTap={{ scale: 0.92 }}
          onClick={() => setIsMiniMenuOpen(!isMiniMenuOpen)}
          className="w-[68px] p-2.5 bg-primary rounded-2xl flex flex-col items-center justify-center gap-1 shadow-xl relative cursor-pointer group"
        >
          <BookOpen size={18} className="text-white group-hover:rotate-12 transition-transform" />
          <span className="text-[10px] text-white font-black tracking-tighter uppercase leading-none">Menu</span>
        </motion.button>

        {/* Nested Miniature Category Popup Context Menu Panel */}
        <AnimatePresence>
          {isMiniMenuOpen && (
            <>
              <div className="fixed inset-0 bg-transparent z-[-1]" onClick={() => setIsMiniMenuOpen(false)} />
              <motion.div
                initial={{ opacity: 0, scale: 0.85, y: 15, x: -20 }}
                animate={{ opacity: 1, scale: 1, y: 0, x: 0 }}
                exit={{ opacity: 0, scale: 0.85, y: 15, x: -20 }}
                className="absolute bottom-[145px] right-0 w-[190px] bg-slate-900 rounded-[24px] p-3 shadow-2xl border border-slate-800 max-h-[280px] overflow-y-auto space-y-1 custom-scrollbar"
              >
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest px-2.5 pb-1.5 border-b border-slate-800/60 mb-1">
                  Jump to Section
                </div>
                {categories.map((cat) => (
                  <button
                    key={cat.id}
                    onClick={() => handleCategorySelect(cat.id)}
                    className={`w-full flex items-center justify-between p-2 rounded-xl text-left font-bold text-xs transition-colors ${
                      activeCategory === cat.id ? 'bg-primary text-white' : 'text-slate-300 hover:bg-slate-800/80'
                    }`}
                  >
                    <span className="truncate pr-2">{cat.name}</span>
                    <span className="text-[10px] opacity-40">
                      {products.filter(p => p.category === cat.id || cat.id === 'all').length}
                    </span>
                  </button>
                ))}
              </motion.div>
            </>
          )}
        </AnimatePresence>

      </div>
    </div>
  );
};

export default App;
